  const margin = 16;
  const ww = Math.max(1, window.innerWidth - margin);
  const wh = Math.max(1, window.innerHeight - margin);
  const scale = Math.max(1, Math.floor(Math.min(ww / W, wh / H)));
  canvas.style.width = (W * scale) + "px";
  canvas.style.height = (H * scale) + "px";
}
window.addEventListener("resize", resizeCanvas);
