function textWidth(s) {
  return s.length ? (s.length * 6 - 1) : 0;
}

function drawText(s, x, y, color) {
  ctx.fillStyle = color || "#ffffff";
  let cx = x;
  for (const ch of s) {
    const bitmap = FONT[ch] || FONT["?"];
    const rows = bitmap.split("/");
    for (let r = 0; r < 7; r++) {
      const row = rows[r];
      for (let c = 0; c < 5; c++) {
        if (row[c] === "1") ctx.fillRect(cx + c, y + r, 1, 1);
      }
    }
    cx += 6;
  }
}

function drawTextCenter(s, y, color) {
  drawText(s, Math.floor((W - textWidth(s)) / 2), y, color);
