function loadHigh() {
  try {
    const v = parseInt(localStorage.getItem("galagaHigh") || "0", 10);
    return isNaN(v) ? 0 : v;
  } catch (err) {
    return 0;
  }
}

function saveHigh() {
  try {
    localStorage.setItem("galagaHigh", String(game.high));
  } catch (err) {
    /* file:// storage may be blocked in some browsers; ignore. */
  }
}

game.high = loadHigh();

/* ============================================================
   STARS
   ============================================================ */
function initStars() {
  game.stars = [];
  const colors = ["#ffffff", "#00ffff", "#ffff00", "#ff8080", "#80ff80", "#ffffff", "#ffffff"];
  for (let i = 0; i < 90; i++) {
    game.stars.push({
      x: Math.random() * W,
      y: Math.random() * H,
      speed: 0.25 + Math.random() * 1.15,
      color: colors[Math.floor(Math.random() * colors.length)],
      tw: Math.random() * Math.PI * 2,
      size: Math.random() < 0.18 ? 2 : 1
    });
  }
}

function updateStars() {
  for (const s of game.stars) {
    s.y += s.speed;
    s.tw += 0.08 + s.speed * 0.03;
    if (s.y >= H) {
      s.y -= H;
      s.x = Math.random() * W;
    }
  }
}

function drawStars() {
  for (const s of game.stars) {
    const a = 0.55 + 0.45 * Math.sin(s.tw);
    ctx.globalAlpha = Math.max(0.15, a);
    ctx.fillStyle = s.color;
    ctx.fillRect(Math.floor(s.x), Math.floor(s.y), s.size, s.size);
  }
  ctx.globalAlpha = 1;
}

/* ============================================================
   FORMATION SLOTS
   ============================================================ */
const formationSlots = [];

function buildSlots() {
  formationSlots.length = 0;
  function addRow(type, count, y, spacing) {
    for (let i = 0; i < count; i++) {
      formationSlots.push({
        type,
        x: W / 2 + (i - (count - 1) / 2) * spacing,
        y
      });
    }
  }
  addRow("boss", 4, 28, 44);
  addRow("goei", 8, 48, 24);
  addRow("goei", 8, 68, 24);
  addRow("zako", 10, 88, 18);
  addRow("zako", 10, 108, 18);
}
buildSlots();

/* ============================================================
